INSERT INTO `projects` (`id`, `name`, `slug`, `type`, `manage`, `start_date`, `end_date`, `status`, `description`, `documents`, `technology`, `created_at`, `updated_at`, `leaders`, `members`) VALUES (95,'Oltao ERP','oltao-erp',NULL,NULL,'2026-11-10','2027-01-31','In Process','<p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\">2.1 The Developer shall design, develop, test, migrate, deploy, document and support the ERP as described in Schedule A, for the Contract Price, within the timeline in Schedule B.</span><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\">2.2 The scope includes </span><b><span style=\"mso-spacerun:\'yes\';font-family:Calibri;mso-ansi-font-weight:bold;\r\nfont-size:11.0000pt;\">every</span></b><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"> feature, module, integration and requirement described in the Proposal (Sections 5, 6 and 7), whether or not it has a separate price line in the Proposal\'s price table. Without limitation, this includes the Amazon, Flipkart and Myntra seller integrations, the Billing &amp; Selling module, Meta Lead Ads, OTP gateway, Cashfree, bank reconciliation (API or statement import), QR codes down to drawer, rack, shelf and bin level, and full data migration from Shopify and Odoo.</span><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\">2.3 Anything reasonably necessary for the ERP to perform as described is included in the Contract Price even if not expressly mentioned, unless the Parties agree otherwise through a signed Change Request.</span><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\">2.4 If the VMS vendor does not provide a usable API within [30] days of the Effective Date, the Developer shall build installation and technician assignment natively in the ERP at no additional cost.</span><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"><o:p></o:p></span></p><p class=\"MsoNormal\"><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\">2.5 </span><b><span style=\"mso-spacerun:\'yes\';font-family:Calibri;mso-ansi-font-weight:bold;\r\nfont-size:11.0000pt;\">Accounting Module.</span></b><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"> The Accounting &amp; Finance Engine described in Section 5.3 of the Proposal is in scope and included in the Contract Price, together with the additional requirements in Clause 4.8.</span><span style=\"mso-spacerun:\'yes\';font-family:Calibri;font-size:11.0000pt;\"><o:p></o:p></span></p>','[\"project-documents\\/1795007924_Software_Development_Services_Agreement_Nine_Oasis_Impex_Warrgyizmorsch_Draft_3 (1).docx\"]','Laravel','2026-11-18 18:48:44','2026-11-18 18:48:44','[\"7\"]','[\"7\"]');
