INSERT INTO `project_phases` (`id`, `project_id`, `name`, `description`, `documents`, `start_date`, `due_date`, `status`, `owner_id`, `sort_order`, `created_by`, `created_at`, `updated_at`) VALUES (1,95,'Phase 0 - Pre-kickoff: contract, repo & team','<p><strong>Goal:</strong> Sign a contract we can deliver, set up client-owned accounts and a clean codebase before week 1.</p><p><strong>Window &amp; payment:</strong> Before week 1 · Milestone 0 Signing = 10% (Roadmap) / 15% advance (draft Agreement 8.2).</p><h4>Scope</h4><ul><li>Settle the 7 contract points in the delivery plan (section 4) plus the roadmap\'s 12 open points</li><li>Attach Roadmap v1.1 as a Schedule or replace Schedule B (draft Schedule B keeps Shopify live to the last milestone, Clause 6.2)</li><li>List pre-existing platform code in Schedule A with a licence (Clause 11.3)</li><li>Fill Schedules D (input dates), E (rate card) and F (key personnel); set the Contract Price incl. on-call and warranty</li><li>Client-owned GitHub, cloud, DNS and secrets vault (Clauses 11.5, 12.1, 12.2)</li><li>Scope clean-up: SaaS layer removed, HRMS removed or hidden before first push</li></ul><h4>Client inputs due</h4><ul><li>Proposal v3 (Annexure 1)</li><li>Kickoff date, peak sales months, accounting opening-balance date</li><li>Client Project Manager name (Schedule F)</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9989; Single-client mode: SaaS layer removed, oltao tenant pinned</li><li>&#9744; Agreement signed with roadmap attached and Schedule A tools listed</li><li>&#9744; Client repository created; code pushed; commits daily from now on</li><li>&#9744; Every team member signed confidentiality + IP undertaking (Clause 19.5)</li><li>&#9744; CI runs tests, static analysis and licence check (Clause 11.4)</li><li>&#9744; Clean build deploys to staging from the client repository</li></ul><h4>Notes / risks</h4><ul><li>Draft Agreement: delay damages 2.5%/week up to 10%; termination after 4 weeks\' delay or 3 failed UATs</li><li>Clause 20.3: every input must be requested in writing 10 working days ahead or the delay is ours</li></ul>',NULL,'2026-10-27','2026-11-09','In Progress',7,1,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(2,95,'Stage 1.1 - Discovery & design','<p><strong>Goal:</strong> Lock requirements, architecture, API contract, migration and test plan, and get every document signed.</p><p><strong>Window &amp; payment:</strong> Weeks 1-3 · Payment Milestone 1 Design sign-off = 5% (delivered wk 3, accepted wk 5).</p><h4>Scope</h4><ul><li>Audit every Shopify call in the Next.js repo and the 22 Shopify apps</li><li>Architecture, database schema, OpenAPI storefront contract</li><li>DPDP design (consent, retention, processor role, 6-hour breach notice)</li><li>Shopify + Odoo migration map and rollback plan (Clause 15.2)</li><li>Test plan, wireframes for new screens, input-request calendar</li><li>Decisions: ADR-0001 interim invoicing owner, store GSTIN + series, API p95 target, blogs source, 3D model hosting, marketplace stock push</li></ul><h4>Client inputs due</h4><ul><li>Razorpay, Cashfree, OTP, email, WhatsApp, Meta / GA4 / Google Ads access - due week 3</li><li>VMS vendor API decision - due week 4</li><li>One approver per module area</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9989; Every Shopify call mapped to an ERP endpoint</li><li>&#9989; OpenAPI storefront contract + Postman collection</li><li>&#9744; Architecture and schema document signed</li><li>&#9744; DPDP design signed</li><li>&#9744; Migration map + rollback plan signed</li><li>&#9744; Test plan signed</li><li>&#9744; Ownership table for stock/dispatch/billing weeks 14-27 agreed (ADR-0001)</li><li>&#9744; Design sign-off certificate received</li></ul><h4>Notes / risks</h4><ul><li>Weeks 20-27 have no clear owner for stock and dispatch - agree ownership table now</li></ul>',NULL,'2026-11-10','2026-11-30','In Progress',7,2,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(3,95,'Stage 1.2 - Commerce core & storefront APIs','<p><strong>Goal:</strong> Run oltao.in fully on the ERP API in staging, with every payment method and conversion tracking working.</p><p><strong>Window &amp; payment:</strong> Weeks 4-9 · Payment Milestone 2 Storefront APIs ready = 12% (delivered wk 9, accepted wk 11).</p><h4>Scope</h4><ul><li>Catalogue (variants, specs, collections, SEO, facet filters), cart, coupons</li><li>Checkout: GST, shipping, COD, partial COD, EMI/BNPL; Razorpay + Cashfree</li><li>Customer OTP accounts, orders, GST invoice, packing slip</li><li>Email/WhatsApp alerts; staff RBAC + 2FA + audit log</li><li>Rate limit, bot and fraud checks; daily backups</li><li>Interim Odoo stock; Meta Pixel + CAPI, GA4, Google Ads, feeds with the same IDs</li></ul><h4>Client inputs due</h4><ul><li>Cashfree test keys</li><li>Shipping charge rules (decision D7)</li><li>Store GSTIN state confirmation</li><li>Odoo API, carriers, auditor - due week 8</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Storefront fully on ERP API in staging</li><li>&#9744; Test order through every payment method</li><li>&#9744; Meta and Google conversions verified; feed IDs unchanged</li><li>&#9744; Storefront API p95 under target (500 ms contract)</li><li>&#9744; Release pack: notes, test results, acceptance checklist</li></ul><h4>Notes / risks</h4><ul><li>Known storefront bug: card links to /products/undefined?id=undefined</li></ul>',NULL,'2026-12-01','2027-01-11','In Progress',7,3,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(4,95,'Stage 1.3 - Shopify cutover','<p><strong>Goal:</strong> Move live oltao.in orders from Shopify to the ERP with no data loss and a tested rollback.</p><p><strong>Window &amp; payment:</strong> Weeks 10-15 · Cutover in week 14 (max 2 h downtime) · Payment Milestone 3 = 10% (delivered wk 14, accepted wk 15).</p><h4>Scope</h4><ul><li>Migration tools with 2 dry runs + reconciliation (counts and money totals)</li><li>Shiprocket, ShadowFox, Delivery One with manual AWB fallback</li><li>Odoo bridge: stock in, orders out, daily accounts export (3 separate switches)</li><li>Customer dashboard v1, 301 redirects, load test at 5x peak</li><li>2-week parallel run (wk 12-13) with automatic order comparison</li><li>CERT-In VAPT, rollback rehearsal, on-call rota from week 14</li></ul><h4>Client inputs due</h4><ul><li>Shopify and Odoo full exports</li><li>Carrier API keys, Odoo API, CERT-In auditor (week 8)</li><li>Agreed low-traffic cutover window in writing</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Every Shopify call mapped; staging storefront on ERP with migrated data</li><li>&#9744; Two migration dry runs; counts and money totals match</li><li>&#9744; Meta/Google purchase and add-to-cart events verified; feed IDs unchanged</li><li>&#9744; Two-week parallel run: price, tax, shipping, payment status match per order</li><li>&#9744; CERT-In Critical/High findings fixed</li><li>&#9744; Switch in low-traffic window; final delta migrated; 301s live</li><li>&#9744; Rollback ready: storefront can repoint to Shopify; Shopify kept 30 days</li><li>&#9744; Daily checks for two weeks; customers log in by OTP; old orders visible</li><li>&#9744; Reconciliation report signed; no Critical/Major open 7 days after cutover</li></ul><h4>Notes / risks</h4><ul><li>Book VAPT to finish by mid week 12 with a retest slot in week 13</li><li>Support SLAs (Schedule C) apply from week 14 - on-call rota needed</li></ul>',NULL,'2027-01-12','2027-02-22','Planned',7,4,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(5,95,'Stage 2.1 - Inventory & QR warehouse','<p><strong>Goal:</strong> One multi-warehouse stock ledger driven by QR scans, feeding live stock to the store.</p><p><strong>Window &amp; payment:</strong> Weeks 16-18 · Payment Milestone 4 = 8% (delivered wk 18, accepted wk 20). Stock bridge from Odoo retires.</p><h4>Scope</h4><ul><li>Storage locations down to drawer, rack, shelf and bin</li><li>QR codes per item, batch and bin; label printing</li><li>Mobile scan screens in Hindi and English</li><li>Low-stock alerts, live storefront availability, count reconciliation</li><li>Opening stock load</li></ul><h4>Client inputs due</h4><ul><li>Signed physical stock count</li><li>Label printer model</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Full receive-to-dispatch cycle by QR scan</li><li>&#9744; Opening stock matches signed count</li><li>&#9744; Live stock showing on store</li><li>&#9744; Odoo stock bridge switched off</li></ul>',NULL,'2027-02-23','2027-03-15','Planned',7,5,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(6,95,'Stage 2.2 - Purchase & dispatch','<p><strong>Goal:</strong> Supply chain in the ERP: purchase to stock, sales to dispatch, returns back to stock.</p><p><strong>Window &amp; payment:</strong> Weeks 19-20 · Payment Milestone 5 Supply chain = 7% (delivered wk 20, accepted wk 22).</p><h4>Scope</h4><ul><li>Suppliers, PO, GRN with QR scan-in, bills, purchase returns</li><li>Transfers, allocation, pick lists, dispatch</li><li>Courier and customer returns</li><li>Reorder suggestions</li></ul><h4>Client inputs due</h4><ul><li>Supplier master</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; PO -> GRN -> bill -> stock</li><li>&#9744; SO -> allocation -> pick -> dispatch</li><li>&#9744; Return restores stock correctly</li></ul>',NULL,'2027-03-16','2027-03-29','Planned',7,6,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(7,95,'Stage 2.3 - Billing & sales channels','<p><strong>Goal:</strong> Compliant billing per GSTIN, marketplaces and dealers in one order queue; Odoo billing retires.</p><p><strong>Window &amp; payment:</strong> Weeks 21-25 · Payment Milestone 6 = 10% (delivered wk 25, accepted wk 27).</p><h4>Scope</h4><ul><li>Quote -> SO -> invoice chain, credit notes</li><li>E-invoice IRN and e-way bill, multi-GSTIN series and consolidated views</li><li>Trade accounts with PO billing and credit terms</li><li>Amazon, Flipkart, Myntra order sync and channel reports</li><li>Dealer portal (OTP login, verification, bulk order, dashboard)</li></ul><h4>Client inputs due</h4><ul><li>Amazon SP-API, Flipkart, Myntra seller API, IRP/e-way API per GSTIN - due week 18</li><li>Dealer master list</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; E-invoice + e-way bill for each GSTIN</li><li>&#9744; One order from each marketplace in the queue</li><li>&#9744; Dealer full journey</li><li>&#9744; Odoo order bridge and billing retired</li></ul><h4>Notes / risks</h4><ul><li>Amazon listing map, FBA warehouse and report upload already built ahead of plan</li></ul>',NULL,'2027-03-30','2027-05-03','Planned',7,7,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(8,95,'Stage 3.1 - Accounting & finance','<p><strong>Goal:</strong> Separate books per entity with automatic postings, approved by the client\'s CA.</p><p><strong>Window &amp; payment:</strong> Weeks 26-28 · Payment Milestone 7 = 8% (delivered wk 28, accepted wk 30). Daily accounts export retires week 30.</p><h4>Scope</h4><ul><li>Chart of accounts, vouchers, auto-posting + recovery queue</li><li>Bank reconciliation, assets, budgets, statements</li><li>GSTR-1 / 3B, multi-currency</li><li>Edit log that cannot be disabled; India-hosted backups (Clause 4.8)</li></ul><h4>Client inputs due</h4><ul><li>Bank statement access / API - due week 23</li><li>CA-approved chart of accounts and opening balances</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Opening balances match</li><li>&#9744; One month replay posts cleanly</li><li>&#9744; One month-end parallel close signed by CA</li><li>&#9744; Tally/Excel export and read-only CA login</li></ul><h4>Notes / risks</h4><ul><li>Decision: native engine vs Zoho/Tally integration</li></ul>',NULL,'2027-05-04','2027-05-24','Planned',7,8,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(9,95,'Stage 3.2 - CRM, warranty & service','<p><strong>Goal:</strong> One customer view across leads, orders, warranty, installation and support; Odoo retires.</p><p><strong>Window &amp; payment:</strong> Weeks 29-33 · Payment Milestone 8 = 10% (delivered wk 33, accepted wk 35).</p><h4>Scope</h4><ul><li>Leads from web, WhatsApp, Meta Lead Ads; pipeline</li><li>Warranty and activation (dealer-sold and store-sold)</li><li>Installation and technician assignment (VMS or native, Clause 2.4)</li><li>Tickets, journeys, MyOperator</li><li>Full customer dashboard</li></ul><h4>Client inputs due</h4><ul><li>Meta Lead Ads permission and MyOperator key - due week 26</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; Meta lead lands automatically</li><li>&#9744; Unified customer view</li><li>&#9744; Dealer warranty activation</li><li>&#9744; CRM and warranty data migrated; Odoo retired</li></ul>',NULL,'2027-05-25','2027-06-28','Planned',7,9,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(10,95,'Stage 3.3 - Hardening, handover & Final Acceptance','<p><strong>Goal:</strong> Secure, documented, trained and handed over; Final Acceptance in week 38.</p><p><strong>Window &amp; payment:</strong> Weeks 34-36 build, Final Acceptance week 38 · Payment Milestone 9 = 10%.</p><h4>Scope</h4><ul><li>Full security and performance tests</li><li>Dashboards</li><li>Technical, API, schema, deployment docs; admin and user manuals in English and Hindi</li><li>Training</li><li>Credential handover, backup restore test</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; All milestones accepted</li><li>&#9744; Parallel run complete; migration reconciliation signed</li><li>&#9744; VAPT: no open Critical or High</li><li>&#9744; All documentation and credentials handed over (Clause 9.5)</li></ul>',NULL,'2027-06-29','2027-08-02','Planned',7,10,52,'2026-11-18 13:44:13','2026-11-18 13:44:13'),(11,95,'Warranty, retention & AMC','<p><strong>Goal:</strong> Keep the system healthy after Go-Live and collect retention.</p><p><strong>Window &amp; payment:</strong> Retention 10% about week 51 (90 days after Go-Live) · Warranty 10 months from Go-Live · AMC optional at 8%/year.</p><h4>Scope</h4><ul><li>Free defect fixes within Schedule C times</li><li>Provider API and GST/e-invoice law updates (Clause 17.2)</li><li>99.5% monthly uptime of storefront API and checkout</li></ul><h4>Exit checklist (definition of done)</h4><ul><li>&#9744; No Critical or Major defect open at day 90</li><li>&#9744; Retention invoice raised</li><li>&#9744; AMC proposal sent before warranty ends</li></ul>',NULL,'2027-08-03','2027-11-01','Planned',7,11,52,'2026-11-18 13:44:13','2026-11-18 13:44:13');
